      "dialogs/smart_pairing.html":
        '<div class="smart-pairing two-column-dialog">  <div class="left-column divider">    <div class="options-list-container">      <div class="$smart-pairing-options-list options-list"></div>    </div>  </div>  <div class="right-column">    <div class="pairing-dialogs-container">      <div class="$connectWithWifiDialog"></div>      <div class="$pairingDialog"></div>      <div class="$remoteResetDialog"></div>    </div>  </div></div>',
      "dialogs/smart_remote_reset.html":
        '<div class="remote-reset">  <div class="icon-dialog-content">    <div class="step-list">      <div class="step-list-title">[[Devices linked to your TV |Title for the "Delete Devices" wizard which shows all devices paired with this TV.|407974865]]</div>      <div class="$list" data-model="{{devices}}">        <div class="{{model.deviceClass}} step">{{model.displayString}}</div>      </div>    </div>    <div class="reset-help">[[Are you sure you want to delete all paired devices?|Tooltip displayed when a user is going to delete her mobile device from the application.]]</div>    <div class="$button remove-remote-button" data-model={{removeRemoteButtonModel}}></div>  </div></div>',
      "dialogs/system_error.html":
        '<div>  <div class="dialog-large-icon {{model.iconClass}}"></div>  <div class="icon-dialog-content">    <div class="link">[[For more info, go to: <a class="base-url">{{displayUrl}}</a>|Prompt directing the user to a website containing more information on the error they have encountered.|704868202]]</div>    <div class="qr-code-wrapper">[[Or scan:|Explains alternative way of accessing help and feedback pages by scanning QR code.|817055224]]      <div class="qr $image" data-image-url="{{imageUrl}}"/>    </div>  </div></div>',
      "dialogs/tos.html":
        '<div>  <div class="dialog-large-icon icon-settings-term"></div>  <div class="icon-dialog-content">    <div class="subtitle">[[To read YouTube\'s Privacy Policy, go to:|Dialog subtitle telling user to go to the following URL to view youtube privacy policy document]]</div>    <div class="url">youtube.com/privacy</div>    <div class="subtitle">[[To read YouTube\'s Terms of Service, go to:|Dialog subtitle telling user to go to the following URL to view youtube terms of service.]]</div>    <div class="url">youtube.com/terms</div>  </div></div>',
      "dialogs/tvfilm_content_panel.html":
        '<div class="tvfilm-content-panel">  <div class="tvfilm-content-panel-body">    <div class="image-container">      <div class="$image tvfilm-item-image" data-image-url="{{model.thumbnailUrl}}"></div>    </div><div class="text-container">      <div class="offer-title">{{model.offerTitle}}</div>      <div class="item-title">{{model.itemTitle}}</div>      <div class="$div-list metadata-rows" data-model="{{model.metadataRows}}"></div>      <div class="$badge tvfilm-badge"></div>    </div>  </div></div>',
      "dialogs/voice_assistant.html":
        '<div aria-hidden="true" id="voice-assistant">  <div class="sound-throbber-container">    <div class="searching-indicator-container">      <div class="searching-indicator"></div>      <div class="searching-indicator-mask1"></div>      <div class="searching-indicator-mask2"></div>    </div>    <div class="sound-throbber-white"></div>    <div class="sound-throbber-red"></div>    <div class="voice-icon icon-mic"></div>  </div>  <div class="hint">[[Speak now|Text telling the user to start talking in order to use Voice Assistant]]</div>  <div class="query">    <div class="$voice-query-fragment-list fragment-list" data-model="{{model.getQuery().getFragments()}}"></div>  </div></div>',
      "dialogs/welcome.html":
        '<div>  <div id="overlay-header" class="warm-welcome" aria-labelledby="welcome-title-1 welcome-title-2" aria-describedby="welcome-description">  <div class="welcome-logo"></div>    <div class="welcome-line-1" id="welcome-title-1">      [[Welcome!|Welcome message title first line.]]    </div>    <div class="welcome-line-2" id="welcome-title-2">      [[Sign in \u2013 it\u2019s free|Second line of welcome message on sign in dialog]]    </div>    <div class="welcome-line-3" id="welcome-description">      [[Add one account or many, and see videos just for you|Welcome message description.]]    </div>    <div class="$button welcome-sign-in-button" role="button" data-model="{{model.getSignInButtonModel()}}"></div>  </div>  <div class="welcome-button-list $lightweight-list" data-model="{{model.getMenuItems()}}" data-is-vertical="true"></div></div>',
